import pandas as pd


def run(inputs: dict) -> dict:
    dim = inputs["dim_account"].copy()
    stg = inputs["stg_account"].copy()

    # Organize existing versions per account_id into mutable lists of dicts.
    versions = {}
    for acc_id, group in dim.groupby("account_id"):
        vlist = []
        for _, row in group.iterrows():
            vlist.append({
                "plan": row["plan"],
                "eff_start_date": row["eff_start_date"],
                "eff_end_date": row["eff_end_date"],
                "is_current": int(row["is_current"]),
            })
        versions[acc_id] = vlist

    # Stable sort by account_id, then update_date ascending (cursor order).
    stg_sorted = stg.sort_values(["account_id", "update_date"], kind="mergesort")

    def plan_eq(a, b):
        a_na = pd.isna(a)
        b_na = pd.isna(b)
        if a_na and b_na:
            return True
        if a_na != b_na:
            return False
        return a == b

    for _, s in stg_sorted.iterrows():
        acc_id = s["account_id"]
        plan = s["plan"]
        upd = s["update_date"]

        if acc_id not in versions or len(versions[acc_id]) == 0:
            versions.setdefault(acc_id, [])
            versions[acc_id].append({
                "plan": plan,
                "eff_start_date": upd,
                "eff_end_date": pd.NaT,
                "is_current": 1,
            })
            continue

        vlist = versions[acc_id]

        # Find the version covering update_date: start <= upd < end (end NULL = open)
        v = None
        for ver in vlist:
            start = ver["eff_start_date"]
            end = ver["eff_end_date"]
            if start <= upd and (pd.isna(end) or upd < end):
                v = ver
                break

        if v is None:
            # update_date is earlier than the account's first version
            f = min(vlist, key=lambda x: x["eff_start_date"])
            vlist.append({
                "plan": plan,
                "eff_start_date": upd,
                "eff_end_date": f["eff_start_date"],
                "is_current": 0,
            })
        else:
            if plan_eq(v["plan"], plan):
                # unchanged -> no-op
                continue
            elif upd == v["eff_start_date"]:
                # same-day correction, no new version
                v["plan"] = plan
            else:
                # split the covering version
                vlist.append({
                    "plan": plan,
                    "eff_start_date": upd,
                    "eff_end_date": v["eff_end_date"],
                    "is_current": v["is_current"],
                })
                v["eff_end_date"] = upd
                v["is_current"] = 0

    # Build output rows
    rows = []
    for acc_id, vlist in versions.items():
        for ver in vlist:
            rows.append({
                "account_id": acc_id,
                "plan": ver["plan"],
                "eff_start_date": ver["eff_start_date"],
                "eff_end_date": ver["eff_end_date"],
                "is_current": ver["is_current"],
            })

    out = pd.DataFrame(
        rows,
        columns=["account_id", "plan", "eff_start_date", "eff_end_date", "is_current"],
    )

    if not out.empty:
        out = out.sort_values(["account_id", "eff_start_date"], kind="mergesort").reset_index(drop=True)

    out["account_id"] = out["account_id"].astype("int64")
    out["eff_start_date"] = pd.to_datetime(out["eff_start_date"])
    out["eff_end_date"] = pd.to_datetime(out["eff_end_date"])
    out["is_current"] = out["is_current"].astype("int64")

    return {"dim_account_out": out}
